#version 300 es

#define HLSLCC_ENABLE_UNIFORM_BUFFERS 0
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
#define UNITY_UNIFORM
#else
#define UNITY_UNIFORM uniform
#endif
#define UNITY_SUPPORTS_UNIFORM_LOCATION 0
#if UNITY_SUPPORTS_UNIFORM_LOCATION
#define UNITY_LOCATION(x) layout(location = x)
#define UNITY_BINDING(x) layout(binding = x, std140)
#else
#define UNITY_LOCATION(x)
#define UNITY_BINDING(x) layout(std140)
#endif
uniform 	vec4 hlslcc_mtx4x4unity_ObjectToWorld[4];
uniform 	vec4 hlslcc_mtx4x4unity_MatrixVP[4];
uniform 	mediump vec4 _Color;
in highp vec4 in_POSITION0;
in highp vec2 in_TEXCOORD0;
in mediump vec4 in_COLOR0;
out highp vec2 vs_TEXCOORD0;
out highp vec2 vs_TEXCOORD1;
out mediump vec4 vs_COLOR0;
vec4 u_xlat0;
vec4 u_xlat1;
void main()
{
    u_xlat0 = in_POSITION0.yyyy * hlslcc_mtx4x4unity_ObjectToWorld[1];
    u_xlat0 = hlslcc_mtx4x4unity_ObjectToWorld[0] * in_POSITION0.xxxx + u_xlat0;
    u_xlat0 = hlslcc_mtx4x4unity_ObjectToWorld[2] * in_POSITION0.zzzz + u_xlat0;
    u_xlat0 = u_xlat0 + hlslcc_mtx4x4unity_ObjectToWorld[3];
    u_xlat1 = u_xlat0.yyyy * hlslcc_mtx4x4unity_MatrixVP[1];
    u_xlat1 = hlslcc_mtx4x4unity_MatrixVP[0] * u_xlat0.xxxx + u_xlat1;
    u_xlat1 = hlslcc_mtx4x4unity_MatrixVP[2] * u_xlat0.zzzz + u_xlat1;
    gl_Position = hlslcc_mtx4x4unity_MatrixVP[3] * u_xlat0.wwww + u_xlat1;
    vs_TEXCOORD0.xy = in_TEXCOORD0.xy;
    vs_TEXCOORD1.xy = in_POSITION0.xy;
    vs_COLOR0 = in_COLOR0 * _Color;
    return;
}


#version 300 es

precision highp float;
precision highp int;
#define HLSLCC_ENABLE_UNIFORM_BUFFERS 0
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
#define UNITY_UNIFORM
#else
#define UNITY_UNIFORM uniform
#endif
#define UNITY_SUPPORTS_UNIFORM_LOCATION 0
#if UNITY_SUPPORTS_UNIFORM_LOCATION
#define UNITY_LOCATION(x) layout(location = x)
#define UNITY_BINDING(x) layout(binding = x, std140)
#else
#define UNITY_LOCATION(x)
#define UNITY_BINDING(x) layout(std140)
#endif
uniform 	mediump vec4 _BurnColor;
uniform 	float _BurnStart;
uniform 	float _Randomness;
uniform 	vec4 _SpriteBoundsMin;
uniform 	vec4 _SpriteBoundsSize;
uniform 	vec4 _MaskSize;
UNITY_LOCATION(0) uniform mediump sampler2D _MainTex;
UNITY_LOCATION(1) uniform mediump sampler2D _DamageMask;
in highp  vec2 vs_TEXCOORD0;
in highp  vec2 vs_TEXCOORD1;
in mediump  vec4 vs_COLOR0;
layout(location = 0) out mediump vec4 SV_Target0;
vec3 u_xlat0;
mediump vec4 u_xlat16_0;
vec4 u_xlat1;
mediump float u_xlat16_2;
vec2 u_xlat3;
bool u_xlatb7;
vec2 u_xlat11;
float u_xlat12;
bool u_xlatb12;
void main()
{
    u_xlat16_0 = texture(_MainTex, vs_TEXCOORD0.xy);
    u_xlat1 = u_xlat16_0 * vs_COLOR0;
    u_xlat16_2 = u_xlat16_0.w * vs_COLOR0.w + -0.00100000005;
    u_xlatb12 = u_xlat16_2<0.0;
    if(u_xlatb12){discard;}
    u_xlat3.xy = vs_TEXCOORD1.xy + (-_SpriteBoundsMin.xy);
    u_xlat11.xy = max(_SpriteBoundsSize.xy, vec2(9.99999975e-05, 9.99999975e-05));
    u_xlat3.xy = u_xlat3.xy / u_xlat11.xy;
    u_xlat3.xy = clamp(u_xlat3.xy, 0.0, 1.0);
    u_xlat12 = texture(_DamageMask, u_xlat3.xy).x;
    u_xlat3.xy = u_xlat3.xy * _MaskSize.xy;
    u_xlat3.xy = floor(u_xlat3.xy);
    u_xlat3.xy = u_xlat3.xy * vec2(123.339996, 456.209991);
    u_xlat3.xy = fract(u_xlat3.xy);
    u_xlat11.xy = u_xlat3.xy + vec2(45.3199997, 45.3199997);
    u_xlat11.x = dot(u_xlat3.xy, u_xlat11.xy);
    u_xlat3.xy = u_xlat11.xx + u_xlat3.xy;
    u_xlat3.x = u_xlat3.y * u_xlat3.x;
    u_xlat3.x = fract(u_xlat3.x);
    u_xlat3.x = u_xlat3.x * 0.600000024 + -0.200000018;
    u_xlat3.x = _Randomness * u_xlat3.x + 0.550000012;
    u_xlatb7 = u_xlat12>=u_xlat3.x;
    if(u_xlatb7){discard;}
    u_xlatb7 = u_xlat12>=_BurnStart;
    u_xlat3.x = max(u_xlat3.x, 0.00100000005);
    u_xlat12 = u_xlat12 / u_xlat3.x;
    u_xlat12 = clamp(u_xlat12, 0.0, 1.0);
    u_xlat12 = u_xlat12 * 0.699999988;
    u_xlat0.xyz = (-u_xlat16_0.xyz) * vs_COLOR0.xyz + _BurnColor.xyz;
    u_xlat0.xyz = vec3(u_xlat12) * u_xlat0.xyz + u_xlat1.xyz;
    SV_Target0.xyz = (bool(u_xlatb7)) ? u_xlat0.xyz : u_xlat1.xyz;
    SV_Target0.w = u_xlat1.w;
    return;
}
